cat > /app/hierarchical_model.stan << 'STANEOF'
data {
  int<lower=1> N;          // number of groups/observations
  array[N] int<lower=0> y;  // successes
  array[N] int<lower=1> n;  // trials
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  array[N] real<lower=0, upper=1> theta;
}
model {
  // prior on (alpha, beta) proportional to (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);
  // hyperpriors
  theta ~ beta(alpha, beta);
  // likelihood
  y ~ binomial(n, theta);
}
STANEOF
echo "Stan file written:"
cat /app/hierarchical_model.stan
